  args: Parameters - parameters (arguments) used to validate for the next command. returns: IList&lt;ValidationResult&gt; - array of ValidationResults.  Examples public class CommandLogger: ICommandInterceptor { public String GetName(ICommand command) { return command.GetName(); } public Task&lt;object&gt; ExecuteAsync(string correlationId, ICommand command, Parameters args) { Console.WriteLine(&#34;Executed command &#34; + command.getName()); return command.ExecuteAsync(correlationId, args); } private IList&lt;ValidationResult&gt; validate(ICommand command, Parameters args) { return command.validate(args); } } var logger = new CommandLogger(); var loggedCommand = new InterceptedCommand(logger, command); // Each called command will output: Executed command &lt;command name&gt;  See also   ICommand   ICommandInterceptor

